func (e *executableSchema) Exec(ctx context.Context) graphql.ResponseHandler {
	opCtx := graphql.GetOperationContext(ctx)
	ec := newExecutionContext(opCtx, e, make(chan graphql.DeferredResult))
	inputUnmarshalers := func() *graphql.InputUnmarshalerIndex {
		return graphql.NewInputUnmarshalerIndex(
			graphql.NewInputUnmarshaler("MapInput", ec.unmarshalInputMapInput),
			graphql.NewInputUnmarshaler("MissingInput", ec.unmarshalInputMissingInput),
			graphql.NewInputUnmarshaler("NestedInput", ec.unmarshalInputNestedInput),
			graphql.NewInputUnmarshaler("NoteInput", ec.unmarshalInputNoteInput),
			graphql.NewInputUnmarshaler("OmittableInput", ec.unmarshalInputOmittableInput),
			graphql.NewInputUnmarshaler("ProbeInput", ec.unmarshalInputProbeInput),
			graphql.NewInputUnmarshaler("ResolvedInput", ec.unmarshalInputResolvedInput),
			graphql.NewInputUnmarshaler("RetypeInput", ec.unmarshalInputRetypeInput),
			graphql.NewInputUnmarshaler("ReviewInput", ec.unmarshalInputReviewInput),
			graphql.NewInputUnmarshaler("ShapesInput", ec.unmarshalInputShapesInput),
			graphql.NewInputUnmarshaler("TagInput", ec.unmarshalInputTagInput),
		)
	}
	first := true

	switch opCtx.Operation.Operation {
	case ast.Query:
		return func(ctx context.Context) *graphql.Response {
			var response graphql.Response
			var data graphql.Marshaler
			if first {
				first = false
				ctx = graphql.WithLazyInputUnmarshalerIndex(ctx, inputUnmarshalers)
				data = ec._queryMiddleware(ctx, opCtx.Operation, func(ctx context.Context) (any, error) {
					return ec._Query(ctx, opCtx.Operation.SelectionSet), nil
				})
			} else {
				if atomic.LoadInt32(&ec.PendingDeferred) > 0 {
					result := <-ec.DeferredResults
					atomic.AddInt32(&ec.PendingDeferred, -1)
					data = result.Result
					response.Path = result.Path
					response.Label = result.Label
					response.Errors = result.Errors
				} else {
					return nil
				}
			}
			var buf bytes.Buffer
			data.MarshalGQL(&buf)
			response.Data = buf.Bytes()
			if atomic.LoadInt32(&ec.Deferred) > 0 {
				hasNext := atomic.LoadInt32(&ec.PendingDeferred) > 0
				response.HasNext = &hasNext
			}

			return &response
		}
	case ast.Mutation:
		return func(ctx context.Context) *graphql.Response {
			if !first {
				return nil
			}
			first = false
			ctx = graphql.WithLazyInputUnmarshalerIndex(ctx, inputUnmarshalers)
			data := ec._mutationMiddleware(ctx, opCtx.Operation, func(ctx context.Context) (any, error) {
				return ec._Mutation(ctx, opCtx.Operation.SelectionSet), nil
			})
			var buf bytes.Buffer
			data.MarshalGQL(&buf)

			return &graphql.Response{
				Data: buf.Bytes(),
			}
		}
	case ast.Subscription:
		next := ec._subscriptionMiddleware(ctx, opCtx.Operation, func(ctx context.Context) (any, error) {
			return ec._Subscription(ctx, opCtx.Operation.SelectionSet), nil
		})

		var buf bytes.Buffer
		return func(ctx context.Context) *graphql.Response {
			buf.Reset()
			data := next(ctx)

			if data == nil {
				return nil
			}
			data.MarshalGQL(&buf)

			return &graphql.Response{
				Data: buf.Bytes(),
			}
		}

	default:
		return graphql.OneShot(graphql.ErrorResponse(ctx, "unsupported GraphQL operation"))
	}
}

type executionContext struct {
	*graphql.ExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot]
}

func newExecutionContext(
	opCtx *graphql.OperationContext,
	execSchema *executableSchema,
	deferredResults chan graphql.DeferredResult,
) *executionContext {
	return &executionContext{
		ExecutionContextState: graphql.NewExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot](
			opCtx,
			(*graphql.ExecutableSchemaState[ResolverRoot, DirectiveRoot, ComplexityRoot])(execSchema),
			parsedSchema,
			deferredResults,
		),
	}
}

